import itertools

def burst(policy, new=1000, refresh_every=250):
    live = [130, 100, 100, 120]
    rr = itertools.cycle(range(4))
    worst = 0
    for i in range(new):
        if i % refresh_every == 0:
            stale = live[:]; window = [0, 0, 0, 0]
        if policy == "least" or (policy == "hybrid" and i % 20 == 0):
            s = min(range(4), key=lambda k: stale[k])
        else:
            s = next(rr)
        live[s] += 1; window[s] += 1
        worst = max(worst, max(window))
    return live, worst

for p in ["least", "hybrid"]:
    print(p, *burst(p))
# least [380, 350, 350, 370] 250
# hybrid [368, 363, 362, 357] 72

class Broker:
    def __init__(self):
        self.orders = {}; self.calls = 0
    def submit(self, key, qty):
        self.calls += 1
        self.orders.setdefault(key, {"qty": qty})  # 같은 키면 새로 만들지 않는다
        if self.calls <= 2:
            raise TimeoutError                     # 처리는 됐는데 응답이 안 온다
        return self.orders[key]

b = Broker(); waits = []
for attempt in range(5):
    try:
        print("응답:", b.submit("toss-order-1", 1)); break
    except TimeoutError:
        waits.append(2 ** attempt)                 # 1, 2, 4, 8 분
print("기다린 간격(분):", waits)
print("브로커 쪽 주문 수:", len(b.orders), "/ 보낸 요청 수:", b.calls)
# 응답: {'qty': 1}
# 기다린 간격(분): [1, 2]
# 브로커 쪽 주문 수: 1 / 보낸 요청 수: 3
